// Client-side site search. The index (search-data.js) is generated by tools/build.py and loaded on first use.
import { $, modal, escapeHtml } from './util.js';

const root = $('#search');
const input = $('#search-input');
const results = $('#search-results');
const hint = $('#search-hint');
let data = null;

const dlg = modal(root, { bodyClass: 'search-open', initialFocus: '#search-input' });

async function load() {
  if (!data) {
    try { data = (await import('../search-data.js')).default; } catch (_) { data = []; hint.textContent = 'Search is unavailable right now.'; }
  }
  return data;
}
const mark = (text, terms) => {
  let out = escapeHtml(text);
  terms.forEach((t) => { out = out.replace(new RegExp(`(${t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'ig'), '<mark>$1</mark>'); });
  return out;
};
async function run() {
  const q = input.value.trim().toLowerCase();
  if (q.length < 2) { results.innerHTML = ''; hint.textContent = 'Try “flat white”, “gluten free” or “parking”.'; return; }
  const idx = await load();
  const terms = q.split(/\s+/).filter(Boolean);
  const scored = [];
  for (const e of idx) {
    const t = e.title.toLowerCase(), x = e.text.toLowerCase();
    if (!terms.every((w) => t.includes(w) || x.includes(w))) continue;
    scored.push({ e, s: terms.reduce((n, w) => n + (t.startsWith(w) ? 6 : t.includes(w) ? 4 : 1), 0) + (e.type === 'Page' ? 0.5 : 0) });
  }
  scored.sort((a, b) => b.s - a.s);
  const top = scored.slice(0, 8);
  hint.textContent = top.length ? `${scored.length} ${scored.length === 1 ? 'result' : 'results'}${scored.length > 8 ? ', showing the top 8' : ''}.` : `Nothing found for “${input.value.trim()}”. Try a simpler word.`;
  results.innerHTML = top.map(({ e }) => `<li><a href="${escapeHtml(e.url)}"><span class="r-type">${escapeHtml(e.type)}</span><span class="r-title">${mark(e.title, terms)}</span><span class="r-text">${mark(e.text.length > 130 ? e.text.slice(0, 127) + '…' : e.text, terms)}</span></a></li>`).join('');
}
$('#search-open').addEventListener('click', (e) => dlg.open(e.currentTarget));
$('#search-close').addEventListener('click', () => dlg.close());
$('#search-form').addEventListener('submit', (e) => { e.preventDefault(); const a = results.querySelector('a'); if (a) a.click(); });
input.addEventListener('input', run);
input.addEventListener('keydown', (e) => { if (e.key === 'ArrowDown') { const a = results.querySelector('a'); if (a) { e.preventDefault(); a.focus(); } } });
results.addEventListener('keydown', (e) => {
  const links = [...results.querySelectorAll('a')]; const i = links.indexOf(document.activeElement);
  if (e.key === 'ArrowDown' && i < links.length - 1) { e.preventDefault(); links[i + 1].focus(); }
  if (e.key === 'ArrowUp') { e.preventDefault(); (i > 0 ? links[i - 1] : input).focus(); }
});
results.addEventListener('click', () => dlg.close());
document.addEventListener('keydown', (e) => {
  if (e.key === '/' && !/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName) && !dlg.isOpen()) { e.preventDefault(); dlg.open($('#search-open')); }
});
